/// <summary>
/// CB166_SalesOrderSubstitutes
/// The <c>METSalesItemSubstituteSearch</c> main class is inspired from PriceDiscPriceAgreementSearch and responsible for the substitutes search
/// </summary>
abstract class METSalesItemSubstituteSearch
{
    const str CacheScopeFindSubstitute = METConstants::CacheScopeFindSubstitute;
    
    METSalesItemSubstituteSearchParameters  salesItemSubstituteSearchParameters;
    METSalesItemSubstitute                  salesItemSubstitute;

    METCustOperGroupId                      custOperGroupId;
    container                               cacheValue;
    boolean                                 cacheMode;

    boolean                                 substituteExists  = false;
    ItemId                                  itemId;

    boolean                                 searchAgain;
    CustParameters                          custParameters;

    ListEnumerator  substituteSiteCodeTypeEnumerator;
    ListEnumerator  substitutePartyCodeTypeEnumerator;

    boolean         continueSearch = true, continueSearchSite = true;

    InventDim       inventDim;

    Set             substitutionCodeSet;

}

Method.Source:
/// <summary>
/// Method to retrieve the cache scope
/// </summary>
/// <returns>The cache scope string</returns>
public static str retrieveCacheScope()
{
    return CacheScopeFindSubstitute;
}

    /// <summary>
    /// Method to create the collection set
    /// </summary>
    /// <param name = "_firstCode">First substitution code to search for</param>
    /// <param name = "_secondCode">Second substitution code to search for. Used only by METSalesItemSubstituteSearch_Enabled</param>
    /// <returns>a <c>Set</c> of substitution codes</returns>
    protected Set createSubstitutionCodeSet(METSalesItemSubstitutionCode _firstCode, METSalesItemSubstitutionCode _secondCode = METSalesItemSubstitutionCode::None)
    {
        Set localSubstitutionCodeSet = new Set(Types::Enum);
        localSubstitutionCodeSet.add(_firstCode);

        if (_secondCode != METSalesItemSubstitutionCode::None)
        {
            localSubstitutionCodeSet.add(_secondCode);
        }

        return localSubstitutionCodeSet;
    }

    /// <summary>
    /// Construct
    /// </summary>
    /// <param name = "_salesLine">Sales order line to search substitute from</param>
    /// <param name = "_substitutionEnabled">Customer substitution enabled</param>
    /// <returns>New instance of <c>METSalesItemSubstituteSearch</c></returns>
    public static METSalesItemSubstituteSearch construct(SalesLine                       _salesLine,
                                                         METSalesItemSubstitutionEnabled _substitutionEnabled)
    {
        METSalesItemSubstituteSearchParameters salesItemSubstituteSearchParameters = METSalesItemSubstituteSearchParameters::construct();
        salesItemSubstituteSearchParameters.parmCustAccount(_salesLine.custAccount);
        salesItemSubstituteSearchParameters.parmInventDim(_salesLine.inventDim());
        salesItemSubstituteSearchParameters.parmItemId(_salesLine.ItemId);

        METSalesItemSubstituteSearch salesItemSubstituteSearch = METSalesItemSubstituteSearch::newFromParameters(salesItemSubstituteSearchParameters, _substitutionEnabled);
        return salesItemSubstituteSearch;
    }

    /// <summary>
    /// Creates a new instance of <c>METSalesItemSubstituteSearch</c> class from the parameters.
    /// </summary>
    /// <param name = "_salesItemSubstituteSearchParameters">The parameters for sales item substitute search.</param>
    /// <param name = "_substitutionEnabled">Customer substitutions enabled.</param>
    /// <returns>An instance of the substitute search class.</returns>
    protected static METSalesItemSubstituteSearch newFromParameters(METSalesItemSubstituteSearchParameters _salesItemSubstituteSearchParameters,
                                                                    METSalesItemSubstitutionEnabled        _substitutionEnabled)
    {
        METSalesItemSubstituteSearch salesItemSubstituteSearch;

        if (_substitutionEnabled)
        {
            salesItemSubstituteSearch = new METSalesItemSubstituteSearch_Enabled();
        }
        else
        {
            salesItemSubstituteSearch = new METSalesItemSubstituteSearch_Disabled();
        }

        salesItemSubstituteSearch.salesItemSubstituteSearchParameters = _salesItemSubstituteSearchParameters;

        salesItemSubstituteSearch.initialize();

        return salesItemSubstituteSearch;
    }

/// <summary>
/// Initialize class variables
/// </summary>
protected void initialize()
{
    custOperGroupId = CustTable::find(salesItemSubstituteSearchParameters.parmCustAccount()).METCustOperGroupId;
    custParameters = CustParameters::find();
    itemId = salesItemSubstituteSearchParameters.parmItemId();
    inventDim = salesItemSubstituteSearchParameters.parmInventDim();
}

/// <summary>
/// Determines whether to continue substitute search.
/// </summary>
/// <param name = "_substitutePartyCodeTypeEnumerator">
/// A party code type enumerator.</param>
/// <param name = "_continueSearch">
/// A Boolean value that indicates whether to continue the substitute search.
/// </param>
/// <returns>
/// true if needs to continue substitute search; otherwise, false.
/// </returns>
protected boolean mustContinueSearch(ListEnumerator _substitutePartyCodeTypeEnumerator, boolean _continueSearch)
{
    return _substitutePartyCodeTypeEnumerator.moveNext() && _continueSearch;
}

protected Set parmSubstitutionCodeSet(Set _substitutionCodeSet = substitutionCodeSet)
{
    substitutionCodeSet = _substitutionCodeSet;
    return substitutionCodeSet;
}

    /// <summary>
    /// Searches for the substitute and returns the substitute record.
    /// </summary>
    /// <returns>METSalesItemSubstitute if a substitute record was found; otherwise, false.</returns>
    public METSalesItemSubstitute search()
    {
        METSalesItemSubstitutionAccountCodeType accountCode;
        CustVendRel     accountRelation;
        TableGroupAll   siteCode;
        InventSiteId    siteRelation;
 
        RefRecId        salesItemSubstituteRefRecId;

        METSubstituteSiteCodeTypeOrderedList  substituteSiteCodeTypeOrderedList  = METSubstituteSiteCodeTypeOrderedList::newFromOrder(SortOrder::Ascending);
        METSubstitutePartyCodeTypeOrderedList substitutePartyCodeTypeOrderedList = METSubstitutePartyCodeTypeOrderedList::newFromOrder(SortOrder::Ascending);

        substituteSiteCodeTypeEnumerator     = substituteSiteCodeTypeOrderedList.getEnumerator();
        substitutePartyCodeTypeEnumerator   = substitutePartyCodeTypeOrderedList.getEnumerator();

        continueSearch = true;
        continueSearchSite = true;
        salesItemSubstitute = null;

        if (substitutionCodeSet.empty())
        {
            return null;
        }

        // Loop through substitute party code type Table > Group > All
        while (substitutePartyCodeTypeEnumerator.moveNext() && continueSearch)
        {
            accountCode        = substitutePartyCodeTypeEnumerator.current();
            accountRelation    = this.accountRelation(accountCode, custOperGroupId);
            continueSearchSite = true;
        
            // For each of the substitute party code type Table > Group > All, search for SO site first and then blank site
            while (this.mustContinueSearch(substituteSiteCodeTypeEnumerator, continueSearch && continueSearchSite))
            {
                siteCode = substituteSiteCodeTypeEnumerator.current();
                siteRelation = this.siteRelation(siteCode);

                if (this.validatePartyRelation(accountCode, accountRelation)
                &&  this.validateSiteRelation(siteCode, siteRelation))
                {
                    // To avoid flooding the cache the most granulated setup isn't cached.
                    cacheMode = (siteCode != TableGroupAll::Table || accountCode != METSalesItemSubstitutionAccountCodeType::Table);

                    cacheValue = conNull();

                    container key;

                    if (cacheMode)
                    {
                        METSalesItemSubstituteCacheKey cacheKey = METSalesItemSubstituteCacheKey::construct();

                        // Initialize the cacheKey
                        // METSalesItemSubstituteSearch_Enabled has substitution code Never, None
                        // METSalesItemSubstituteSearch_Disabled has substitution code Never, Replacement and OutOfStock
                        cacheKey.initialize(siteCode, siteRelation, accountCode, accountRelation, itemId);

                        key = cacheKey.pack();

                        cacheValue = METSalesItemSubstituteCacheKey::getSalesItemSubstituteCacheValue(CacheScopeFindSubstitute, key);
                    }

                    ValidFromDate           fromDate;
                    ValidToDate             toDate;
                    METSubstituteItemID     substituteItemId;
                    METSalesItemSubstitutionRounding    rounding;

                    salesItemSubstituteRefRecId = 0;
                    searchAgain = false;

                    if (cacheValue == conNull())
                    {
                        Query query = this.buildFindSalesItemSubstituteQuery(siteRelation, accountCode, accountRelation, itemId, substitutionCodeSet);

                        QueryRun queryRun = new QueryRun(query);
                        while (queryRun.next())
                        {
                            salesItemSubstitute = queryRun.get(tableNum(METSalesItemSubstitute));

                            if (cacheMode)
                            {
                                // For METSalesItemSubstituteSearch_Enabled, we force the cacheKey substitutionCode to None
                                // Therefore salesItemSubstitute.SubstitutionCode is added in the cacheValue for METSalesItemSubstituteSearch_Enabled
                                // We don't really need it for METSalesItemSubstituteSearch_Disabled but easier to manage from a code point of view
                                cacheValue += [[salesItemSubstitute.ValidFrom,
                                            salesItemSubstitute.ValidTo,
                                            salesItemSubstitute.SubstituteItemId,
                                            salesItemSubstitute.RecId,
                                            salesItemSubstitute.Rounding,
                                            salesItemSubstitute.SubstitutionCode]];
                            }
                            else
                            {
                                fromDate                    = salesItemSubstitute.ValidFrom;
                                toDate                      = salesItemSubstitute.ValidTo;
                                salesItemSubstituteRefRecId = salesItemSubstitute.RecId;

                                // Method to check if valid salesItemSubstitute
                                // Giving _substituteRefRecId 0 as a parameter to avoid reselecting salesItemSubstitute from above
                                continueSearch = this.continueSearch(fromDate, toDate, 0, salesItemSubstitute.SubstituteItemId, salesItemSubstitute.SubstitutionCode, substitutionCodeSet);
                                if (!continueSearch)
                                {
                                    break;
                                }
                            }
                        }

                        if (cacheMode)
                        {
                            //We also want to cache the absence of substitutes.
                            if (cacheValue == conNull())
                            {
                                cacheValue = [[0]];
                            }

                            // add cacheValue against the key in the cache
                            METSalesItemSubstituteCacheKey::insertSalesItemSubstituteCache(CacheScopeFindSubstitute, key, cacheValue);
                        }
                    }

                    if (cacheMode && cacheValue)
                    {
                        for (int i=1; i<=conLen(cacheValue); i++)
                        {
                            // Adding cachedSubstitutionCode for METSalesItemSubstituteSearch_Enabled even though we don't need it for disabled, easier to manage
                            METSalesItemSubstitutionCode cachedSubstitutionCode;
                            [fromDate, toDate, substituteItemId, salesItemSubstituteRefRecId, rounding, cachedSubstitutionCode] = conPeek(cacheValue, i);
                            
                            if (salesItemSubstituteRefRecId)
                            {
                                //salesItemSubstitute = METSalesItemSubstitute::findRecId(salesItemSubstituteRefRecId);

                                // Method to check if valid salesItemSubstitute
                                continueSearch = this.continueSearch(fromDate, toDate, salesItemSubstituteRefRecId, substituteItemId, cachedSubstitutionCode, substitutionCodeSet);
                                if (!continueSearch)
                                {
                                    break;
                                }
                            }
                        }
                    }
                }
            }
            substituteSiteCodeTypeEnumerator.reset();
        }

        return salesItemSubstitute;
    }

/// <summary>
/// Specifies the site relation for a given <c>TableGroupAll</c> during finding the substitute.
/// </summary>
/// <param name = "_siteCode">The site code type to specify the site relation for.</param>
/// <returns>Returns site relation to find the substitute for.</returns>
/// <remarks>We are only managing specific site or all sites.</remarks>
protected InventSiteId siteRelation(TableGroupAll   _siteCode)
{
    switch (_siteCode)
    {
        case TableGroupAll::Table:
            return salesItemSubstituteSearchParameters.parmInventDim().InventSiteId;
        default:
            return '';
    }
}

/// <summary>
/// Returns the account relation for a given <c>METSalesItemSubstitutionAccountCodeType</c> during finding the substitute.
/// </summary>
/// <param name = "_accountCode">The party code type to return the account number for.</param>
/// <param name = "_groupId">The customer operations group Id.</param>
/// <returns>Returns the account relation to to find the substitute for.</returns>
protected CustVendAC accountRelation(METSalesItemSubstitutionAccountCodeType _accountCode,
                                     METCustOperGroupId                      _groupId)
{
    switch (_accountCode)
    {
        case METSalesItemSubstitutionAccountCodeType::Table:
            return salesItemSubstituteSearchParameters.parmCustAccount();
        case METSalesItemSubstitutionAccountCodeType::GroupId:
            return _groupId;
        default:
            return '';
    }
}

    /// <summary>
    /// Validate party relation
    /// </summary>
    /// <param name = "_code">Substitution account code type</param>
    /// <param name = "_relation">account relation</param>
    /// <returns>true if validation successful; otherwise, false.</returns>
    public boolean validatePartyRelation(METSalesItemSubstitutionAccountCodeType _code, str _relation)
    {
        boolean  ok = true;

        if (_relation && _code == METSalesItemSubstitutionAccountCodeType::All)
        {
            ok = false;
        }

        if (!_relation && _code != METSalesItemSubstitutionAccountCodeType::All)
        {
            ok = false;
        }

        return ok;
    }

    /// <summary>
    /// Validate site relation
    /// </summary>
    /// <param name = "_code">Site code type</param>
    /// <param name = "_relation">site relation</param>
    /// <returns>true if validation successful; otherwise, false.</returns>
    public boolean validateSiteRelation(TableGroupAll _code, str _relation)
    {
        boolean  ok = true;

        if (_relation && _code == TableGroupAll::All)
        {
            ok = false;
        }

        if (!_relation && _code != TableGroupAll::All)
        {
            ok = false;
        }

        return ok;
    }

    /// <summary>
    /// Builds the query for finding substitutes based on the parameters.
    /// </summary>
    /// <param name = "_siteRelation">Site relation</param>
    /// <param name = "_accountCode">An account code.</param>
    /// <param name = "_accountRelation">A customer or customer operations group.</param>
    /// <param name = "_itemId">An <c>ItemId</c>.</param>
    /// <param name = "_substitutionCodeSet">A <c>Set</c> of substitution codes.</param>
    /// <returns>A <c>Query</c> object.</returns>
    protected Query buildFindSalesItemSubstituteQuery(InventSiteId                              _siteRelation,
                                                      METSalesItemSubstitutionAccountCodeType   _accountCode,
                                                      CustVendRel                               _accountRelation,
                                                      ItemId                                    _itemId,
                                                      Set                                       _substitutionCodeSet)
    {
        Query query = new Query();
        
        // Get all records valid from today onwards so they can be added as cache values
        // This is to manage scenario with future dates for substitutes
        query.validTimeStateDateRange(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()), maxDate());
        QueryBuildDataSource qbds = query.addDataSource(tableNum(METSalesItemSubstitute));

        qbds.addRange(fieldNum(METSalesItemSubstitute, InventSiteId)).value(queryValue(_siteRelation));
        qbds.addRange(fieldNum(METSalesItemSubstitute, AccountCode)).value(queryValue(_accountCode));
        qbds.addRange(fieldNum(METSalesItemSubstitute, AccountRelation)).value(queryValue(_accountRelation));
        qbds.addRange(fieldNum(METSalesItemSubstitute, ItemId)).value(queryValue(_itemId));

        return query;
    }

    /// <summary>
    /// method to add the substitution code filter
    /// </summary>
    /// <param name = "_qbds"><c>QueryBuildDataSource</c> for table METSalesItemSubstitute</param>
    /// <param name = "_substitutionCodeSet">A <c>Set</c> of substitution codes.</param>
    /*protected void addQuerySubstitutionCodeRange(QueryBuildDataSource _qbds, Set _substitutionCodeSet)
