            SetEnumerator se = _substitutionCodeSet.getEnumerator();
            se.reset();
            while (se.moveNext())
            {
                _qbds.addRange(fieldNum(METSalesItemSubstitute, SubstitutionCode)).value(queryValue(se.current()));
            }
        }
    }*/

    /// <summary>
    /// This method will check and compare the substitute dates to make sure it's effective as we could get futur substitutes in the cacheValue
    /// </summary>
    /// <param name = "_fromDate">From date.</param>
    /// <param name = "_toDate">To date.</param>
    /// <returns>
    /// True if it meets the date conditions; otherwise, false.
    /// </returns>
    protected boolean doesDateQualifyForFindingSubstitute(FromDate _fromDate, ToDate _toDate)
    {
        TransDate today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        
        return ((today >= _fromDate || !_fromDate)
            && (today <= _toDate || !_toDate));
    }

/// <summary>
/// Check if a substitution code exists in the set of substitution codes
/// </summary>
/// <param name = "_substitutionCode">Substitution code to search for</param>
/// <param name = "_substitutionCodeSet">A <c>Set</c> of substitution codes.</param>
/// <returns>True if it exists; otherwise, false</returns>
protected boolean doesSubstituteCodeQualifyForFindingSubstitute(METSalesItemSubstitutionCode _substitutionCode, Set _substitutionCodeSet)
{        
    return _substitutionCodeSet.in(_substitutionCode);
}

    /// <summary>
    /// Method to determine substitute is found and continue or stop search.
    /// </summary>
    /// <param name = "_fromDate">Substitute effective date</param>
    /// <param name = "_toDate">Substitute expiration date</param>
    /// <param name = "_substituteRefRecId">Substitute record id</param>
    /// <param name = "_substituteItemId">Substitute item number</param>
    /// <param name = "_substitutionCode">Substitution code to search for</param>
    /// <param name = "_substitutionCodeSet">A <c>Set</c> of substitution codes.</param>
    /// <returns>True to continue the search if no substitute found or valid; otherwise, false</returns>
    protected boolean continueSearch(ValidFromDate                  _fromDate,
                                     ValidToDate                    _toDate, 
                                     RefRecId                       _substituteRefRecId,
                                     METSubstituteItemID            _substituteItemId,
                                     METSalesItemSubstitutionCode   _substitutionCode,
                                     Set                            _substitutionCodeSet)
    {
        boolean ret = true;

        // check if it's a valid substitute record for the search
        if (this.doesDateQualifyForFindingSubstitute(_fromDate, _toDate)
        &&  this.doesSubstituteCodeQualifyForFindingSubstitute(_substitutionCode, _substitutionCodeSet))
        {            
            substituteExists = this.substituteExists(_substituteRefRecId, _substituteItemId, _substitutionCode);
        }

        if (substituteExists)
        {
            ret = false;
        }

        return ret;
    }

    /// <summary>
    /// Main method to determine if substitute exists and valid
    /// Overridden in METSalesItemSubstituteSearch_Enabled as few other validation applies
    /// </summary>
    /// <param name = "_substituteRefRecId">Substitute record id</param>
    /// <param name = "_substituteItemId">Substitute item number</param>
    /// <param name = "_substitutionCode">Substitution code</param>
    /// <returns>True if substitute found and valid; otherwise, false</returns>
    protected boolean substituteExists(RefRecId                     _substituteRefRecId,
                                       METSubstituteItemID          _substituteItemId,
                                       METSalesItemSubstitutionCode _substitutionCode)
    {
        boolean ret = true;

        if (_substituteRefRecId)
        {
            salesItemSubstitute = METSalesItemSubstitute::findRecId(_substituteRefRecId);
        }

        return ret;
    }
